                return 0;
            }
            if(item->kind!=TERM_ATOM||strlen(item->name)!=1) {
                s->error=type_error("character",item);
                return 0;
            }
            add_text(&text,item->name);
        }
        return u(s,a,atom(text.text?text.text:""));
    }
    return 0;
}

