const Operator *infix_operator(const char *name) {
    for(size_t i=0;i<sizeof operators/sizeof *operators;++i)if(!strcmp(name,operators[i].name))return &operators[i];
    return NULL;
}
int prefix_priority(const char *name) {
    return !strcmp(name,"\\+")?900:!strcmp(name,"-")?200:0;
}
int symbol_character(int c) {
    return c&&strchr("+-*/\\^<>=~:.?@#&$",c)!=NULL;
}
static void token_add(Reader *r,Token t,int *capacity) {
    if(r->count==*capacity) {
        int n=*capacity?*capacity*2:64;
        Token *p=make((size_t)n*sizeof *p);
        if(r->count)memcpy(p,r->tokens,(size_t)r->count*sizeof *p);
        r->tokens=p;
        *capacity=n;
    }
    r->tokens[r->count++]=t;
}
Reader tokenize(const char *s,int column) {
    Reader r= {
        0
    };
    int i=0,line=1,col=column,whitespace=1,capacity=0;
    while(s[i]) {
        if(s[i]==' '||s[i]=='\n') {
            whitespace=1;
            if(s[i++]=='\n') {
                ++line;
                col=1;
            }
            else ++col;
            continue;
        }
        if(s[i]=='%') {
            whitespace=1;
            while(s[i]&&s[i]!='\n') {
                ++i;
                ++col;
            }
            continue;
        }
        Token t= {
            .line=line,.column=col,.space=whitespace
        };
        whitespace=0;
        int start=i;
        char c=s[i];
        if(isdigit((unsigned char)c)) {
            long long n=0;
            while(isdigit((unsigned char)s[i])) {
                if(n<=INT32_MAX)n=10*n+s[i]-'0';
                ++i;
                ++col;
            }
            if(n>INT32_MAX) {
                t.kind=TOKEN_INVALID;
                t.name=copy_string("integer too large");
            }
            else {
                t.kind=TOKEN_INTEGER;
                t.integer=n;
            }
        }
        else if(isalpha((unsigned char)c)||c=='_') {
            while(isalnum((unsigned char)s[i])||s[i]=='_') {
                ++i;
                ++col;
            }
            t.kind=c>='a'&&c<='z'?TOKEN_NAME:TOKEN_VARIABLE;
        }
        else if(symbol_character(c)) {
            while(symbol_character(s[i])) {
                ++i;
                ++col;
            }
            t.kind=i-start==1&&c=='.'&&(!s[i]||s[i]==' '||s[i]=='\n'||s[i]=='%')?TOKEN_END:TOKEN_NAME;
        }
        else if(c=='!'||c==';') {
            t.kind=TOKEN_NAME;
            ++i;
            ++col;
        }
        else if(strchr(",|()[]",c)) {
            t.kind=TOKEN_PUNCT;
            ++i;
            ++col;
        }
        else if(c=='\'') {
            Buffer name= {
                0
            };
            ++i;
            ++col;
            int closed=0,bad=0;
            while(s[i]&&s[i]!='\n') {
                char ch=s[i];
                if(ch=='\''&&s[i+1]=='\'') {
                    add_bytes(&name,"'",1);
                    i+=2;
                    col+=2;
                }
                else if(ch=='\'') {
                    ++i;
                    ++col;
                    closed=1;
                    break;
                }
                else if(ch=='\\') {
                    ++i;
                    ++col;
                    if(!s[i]||s[i]=='\n')continue;
                    ch=s[i++];
                    ++col;
                    if(ch=='n')ch='\n';
                    else if(ch=='t')ch='\t';
                    else if(ch!='\\'&&ch!='\'')bad=1;
                    add_bytes(&name,&ch,1);
                }
                else {
                    add_bytes(&name,&ch,1);
                    ++i;
                    ++col;
                }
            }
            if(!closed) {
                t.kind=TOKEN_INVALID;
                t.name=copy_string("unterminated quoted atom");
            }
            else if(bad) {
                t.kind=TOKEN_INVALID;
                t.name=copy_string("undefined escape sequence");
            }
            else {
                t.kind=TOKEN_QUOTED;
                t.name=name.text?name.text:copy_string("");
            }
        }
        else {
            t.kind=TOKEN_INVALID;
            char text[40];
            sprintf(text,"illegal character '%c'",c);
            t.name=copy_string(text);
            ++i;
            ++col;
        }
        t.text=make((size_t)(i-start)+1);
        memcpy(t.text,s+start,(size_t)(i-start));
        if(!t.name)t.name=t.text;
        token_add(&r,t,&capacity);
    }
    Token eof= {
        .kind=TOKEN_EOF,.line=line,.column=col,.space=whitespace,.text="",.name=""
    };
    token_add(&r,eof,&capacity);
    return r;
}
static Token *peek(Reader *r) {
    return &r->tokens[r->at<r->count?r->at:r->count-1];
}
static void syntax_error(Reader *r,int at,const char *message) {
    r->error_at=at;
    Token t=r->tokens[at];
    if(message)r->error=copy_string(message);
    else if(t.kind==TOKEN_INVALID)r->error=t.name;
    else if(t.kind==TOKEN_EOF)r->error=copy_string("unexpected end of file");
    else if(t.kind==TOKEN_END)r->error=copy_string("unexpected end of clause");
    else if(t.kind==TOKEN_NAME&&infix_operator(t.name))r->error=copy_string("operator priority clash");
    else {
        Buffer b= {
            0
        };
        add_format(&b,"unexpected \"%s\"",t.text);
        r->error=b.text;
    }
    longjmp(r->failure,1);
}
static void expect(Reader *r,const char *name) {
    int at=r->at;
    Token *t=peek(r);
    if(t->kind!=TOKEN_PUNCT||strcmp(t->name,name))syntax_error(r,at,NULL);
    ++r->at;
}
static Term *read_variable(Reader *r,Token t) {
    if(strcmp(t.name,"_"))for(int i=0;i<r->nv;++i)if(!strcmp(r->variables[i].name,t.name)) {
        ++r->variables[i].occurrences;
        return r->variables[i].term;
    }
    ReadVariable *vars=make((size_t)(r->nv+1)*sizeof *vars);
    if(r->nv)memcpy(vars,r->variables,(size_t)r->nv*sizeof *vars);
    r->variables=vars;
    Term *v=fresh();
    vars[r->nv++]=(ReadVariable) {
        t.name,v,1
    };
    return v;
}
static Term *read_term(Reader *r,int limit,int *priority);
static int starts_term(Token *t) {
    return t->kind==TOKEN_INTEGER||t->kind==TOKEN_VARIABLE||t->kind==TOKEN_QUOTED||(t->kind==TOKEN_PUNCT&&(!strcmp(t->name,"(")||!strcmp(t->name,"[")))||(t->kind==TOKEN_NAME&&(!infix_operator(t->name)||prefix_priority(t->name)));
}
static void add_argument(Term ***args,int *n,Term *term) {
    Term **items=make((size_t)(*n+1)*sizeof *items);
    if(*n)memcpy(items,*args,(size_t)*n*sizeof *items);
    *args=items;
    items[(*n)++]=term;
}
static Term *primary(Reader *r,int limit,int *priority) {
    int at=r->at++;
    Token t=r->tokens[at];
    *priority=0;
    if(t.kind==TOKEN_INTEGER)return integer(t.integer);
    if(t.kind==TOKEN_VARIABLE)return read_variable(r,t);
    if(t.kind==TOKEN_PUNCT&&!strcmp(t.name,"(")) {
        int p;
        Term *inside=read_term(r,1200,&p);
        expect(r,")");
        return inside;
    }
    if(t.kind==TOKEN_PUNCT&&!strcmp(t.name,"[")) {
        if(peek(r)->kind==TOKEN_PUNCT&&!strcmp(peek(r)->name,"]")) {
            ++r->at;
            return atom("[]");
        }
        Term **elements=NULL;
        int n=0,p;
        add_argument(&elements,&n,read_term(r,999,&p));
        while(peek(r)->kind==TOKEN_PUNCT&&!strcmp(peek(r)->name,",")) {
            ++r->at;
            add_argument(&elements,&n,read_term(r,999,&p));
        }
        Term *tail=atom("[]");
        if(peek(r)->kind==TOKEN_PUNCT&&!strcmp(peek(r)->name,"|")) {
            ++r->at;
            tail=read_term(r,999,&p);
        }
        expect(r,"]");
        return list(elements,n,tail);
    }
    if(t.kind==TOKEN_NAME||t.kind==TOKEN_QUOTED) {
        Token *next=peek(r);
        if(next->kind==TOKEN_PUNCT&&!strcmp(next->name,"(")&&!next->space) {
            ++r->at;
            Term **args=NULL;
            int n=0,p;
            add_argument(&args,&n,read_term(r,999,&p));
            while(peek(r)->kind==TOKEN_PUNCT&&!strcmp(peek(r)->name,",")) {
                ++r->at;
                add_argument(&args,&n,read_term(r,999,&p));
            }
            expect(r,")");
            return compound(t.name,n,args);
        }
        if(t.kind==TOKEN_NAME&&!strcmp(t.name,"-")&&next->kind==TOKEN_INTEGER&&!next->space) {
            ++r->at;
            return integer(-next->integer);
        }
        int p=t.kind==TOKEN_NAME?prefix_priority(t.name):0;
        if(p&&starts_term(next)) {
            if(p>limit)syntax_error(r,at,"operator priority clash");
            int rp;
            Term *arg=read_term(r,p,&rp);
            *priority=p;
            return unary(t.name,arg);
        }
        return atom(t.name);
    }
    syntax_error(r,at,NULL);
    return NULL;
}
static Term *read_term(Reader *r,int limit,int *priority) {
    Term *term=primary(r,limit,priority);
    for(;;) {
        Token *t=peek(r);
        const Operator *op=(t->kind==TOKEN_NAME||(t->kind==TOKEN_PUNCT&&!strcmp(t->name,",")))?infix_operator(t->name):NULL;
        if(!op||op->priority>limit||*priority>op->left)break;
        ++r->at;
        int p;
        Term *right=read_term(r,op->right,&p);
        term=binary(op->name,term,right);
        *priority=op->priority;
    }
    return term;
}
void reader_reset_variables(Reader *r) {
    r->variables=NULL;
    r->nv=0;
    r->error=NULL;
    r->error_at=-1;
}
Term *read_clause(Reader *r,int query) {
    reader_reset_variables(r);
    if(setjmp(r->failure))return NULL;
    int p;
    Term *term=read_term(r,1200,&p);
    int end=r->at++;
    if(r->tokens[end].kind!=TOKEN_END)syntax_error(r,end,NULL);
    if(query&&peek(r)->kind!=TOKEN_EOF)syntax_error(r,r->at,NULL);
    return term;
}

#include "prolog.h"
Memory *memory=NULL;
void *make(size_t n) {
    Memory *p=calloc(1,sizeof *p+(n?n:1));
    if(!p)exit(EXIT_FAILURE);
    p->next=memory;
    memory=p;
    return p+1;
}
char *copy_string(const char *s) {
    char *p=make(strlen(s)+1);
    strcpy(p,s);
    return p;
}
void release_to(Memory *mark) {
    while(memory!=mark) {
        Memory *p=memory;
        memory=p->next;
        free(p);
    }
}
void add_bytes(Buffer *b,const char *s,size_t n) {
    if(b->length+n+1>b->capacity) {
        size_t capacity=(b->length+n+1)*2;
        char *p=make(capacity);
        if(b->length)memcpy(p,b->text,b->length);
        b->text=p;
        b->capacity=capacity;
    }
    memcpy(b->text+b->length,s,n);
    b->length+=n;
    b->text[b->length]=0;
}
void add_text(Buffer *b,const char *s) {
    add_bytes(b,s,strlen(s));
}
void add_format(Buffer *b,const char *fmt,...) {
    va_list args,copy;
    va_start(args,fmt);
    va_copy(copy,args);
    int n=vsnprintf(NULL,0,fmt,copy);
    va_end(copy);
    char *s=make((size_t)n+1);
    vsnprintf(s,(size_t)n+1,fmt,args);
    va_end(args);
    add_text(b,s);
}
char *file_text(const char *path) {
    FILE *f=fopen(path,"r");
    if(!f)exit(EXIT_FAILURE);
    Buffer b= {
        0
    };
    char chunk[4096];
    size_t n;
    while((n=fread(chunk,1,sizeof chunk,f)))add_bytes(&b,chunk,n);
    fclose(f);
    return b.text?b.text:copy_string("");
}
char *line_read(FILE *f) {
    Buffer b= {
        0
    };
    int c;
    while((c=fgetc(f))!=EOF&&c!='\n') {
        char x=(char)c;
        add_bytes(&b,&x,1);
    }
    if(c==EOF&&!b.length)return NULL;
    return b.text?b.text:copy_string("");
}
Term *integer(long long n) {
    Term *t=make(sizeof *t);
    t->kind=TERM_INTEGER;
    t->integer=n;
    return t;
}
Term *atom(const char *name) {
    Term *t=make(sizeof *t);
    t->kind=TERM_ATOM;
    t->name=copy_string(name);
    return t;
}
Term *fresh(void) {
    Term *t=make(sizeof *t);
    t->kind=TERM_VARIABLE;
    return t;
}
Term *compound(const char *name,int n,Term **args) {
    Term *t=make(sizeof *t);
    t->kind=TERM_COMPOUND;
    t->name=copy_string(name);
    t->arity=n;
    t->args=make((size_t)n*sizeof *t->args);
    memcpy(t->args,args,(size_t)n*sizeof *t->args);
    return t;
}
Term *unary(const char *name,Term *a) {
    Term *args[]= {
        a
    };
    return compound(name,1,args);
}
Term *binary(const char *name,Term *a,Term *b) {
    Term *args[]= {
        a,b
    };
    return compound(name,2,args);
}
Term *ternary(const char *name,Term *a,Term *b,Term *c) {
    Term *args[]= {
        a,b,c
    };
    return compound(name,3,args);
}
Term *dereference(Term *t) {
    while(t->kind==TERM_VARIABLE&&t->binding)t=t->binding;
    return t;
}
int is_term(Term *t,const char *name,int arity) {
    t=dereference(t);
    return (arity?t->kind==TERM_COMPOUND&&t->arity==arity:t->kind==TERM_ATOM)&&!strcmp(t->name,name);
}
int empty_list(Term *t) {
    return is_term(t,"[]",0);
}
Term *list(Term **items,int count,Term *tail) {
    Term *result=tail?tail:atom("[]");
    for(int i=count-1;i>=0;--i)result=binary(".",items[i],result);
    return result;
}
int list_items(Term *t,Term ***items,Term **tail) {
    int n=0,capacity=0;
    Term **data=NULL;
    while(is_term(t,".",2)) {
        t=dereference(t);
        if(n==capacity) {
            capacity=capacity?2*capacity:8;
            Term **p=make((size_t)capacity*sizeof *p);
            if(n)memcpy(p,data,(size_t)n*sizeof *p);
            data=p;
        }
        data[n++]=dereference(t->args[0]);
        t=t->args[1];
    }
    *items=data;
    *tail=dereference(t);
    return n;
}
static Term *copy_with(Term *t,Term ***old,Term ***new,int *n) {
    t=dereference(t);
    if(t->kind==TERM_VARIABLE) {
        for(int i=0;i<*n;++i)if((*old)[i]==t)return (*new)[i];
        Term **a=make((size_t)(*n+1)*sizeof *a),**b=make((size_t)(*n+1)*sizeof *b);
        if(*n) {
            memcpy(a,*old,(size_t)*n*sizeof *a);
            memcpy(b,*new,(size_t)*n*sizeof *b);
        }
        a[*n]=t;
        b[*n]=fresh();
        *old=a;
        *new=b;
        return b[(*n)++];
    }
    if(t->kind!=TERM_COMPOUND)return t;
    Term **args=make((size_t)t->arity*sizeof *args);
    for(int i=0;i<t->arity;++i)args[i]=copy_with(t->args[i],old,new,n);
    return compound(t->name,t->arity,args);
}
Term *copy_term(Term *t) {
    Term **a=NULL,**b=NULL;
    int n=0;
    return copy_with(t,&a,&b,&n);
}
Term *copy_pair(Term *head,Term *body,Term **new_body) {
    Term **a=NULL,**b=NULL;
    int n=0;
    Term *h=copy_with(head,&a,&b,&n);
    *new_body=body?copy_with(body,&a,&b,&n):NULL;
    return h;
}
Term *indicator(const char *name,int arity) {
    return binary("/",atom(name),integer(arity));
}
Term *type_error(const char *expected,Term *actual) {
    return binary("type_error",atom(expected),actual);
}
Term *domain_error(const char *domain,Term *actual) {
    return binary("domain_error",atom(domain),actual);
}
Term *evaluation_error(const char *name) {
    return unary("evaluation_error",atom(name));
}

#include "prolog.h"
static void bind(Trail *trail,Term *variable,Term *value) {
    if(trail->count==trail->capacity) {
        int capacity=trail->capacity?trail->capacity*2:64;
        Term **data=realloc(trail->variables,(size_t)capacity*sizeof *data);
        if(!data)exit(EXIT_FAILURE);
        trail->variables=data;
        trail->capacity=capacity;
    }
    trail->variables[trail->count++]=variable;
    variable->binding=value;
}
int unify(Trail *trail,Term *a,Term *b) {
    a=dereference(a);
    b=dereference(b);
    if(a==b)return 1;
    if(a->kind==TERM_VARIABLE) {
        bind(trail,a,b);
        return 1;
    }
    if(b->kind==TERM_VARIABLE) {
        bind(trail,b,a);
        return 1;
    }
    if(a->kind!=b->kind)return 0;
    if(a->kind==TERM_INTEGER)return a->integer==b->integer;
    if(strcmp(a->name,b->name))return 0;
    if(a->kind==TERM_ATOM)return 1;
    if(a->arity!=b->arity)return 0;
    for(int i=0;i<a->arity;++i)if(!unify(trail,a->args[i],b->args[i]))return 0;
    return 1;
}
void undo(Trail *trail,int mark) {
    while(trail->count>mark)trail->variables[--trail->count]->binding=NULL;
}
int identical(Term *a,Term *b) {
    a=dereference(a);
    b=dereference(b);
    if(a==b)return 1;
    if(a->kind!=b->kind||a->kind==TERM_VARIABLE)return 0;
    if(a->kind==TERM_INTEGER)return a->integer==b->integer;
    if(strcmp(a->name,b->name))return 0;
    if(a->kind==TERM_ATOM)return 1;
    if(a->arity!=b->arity)return 0;
    for(int i=0;i<a->arity;++i)if(!identical(a->args[i],b->args[i]))return 0;
    return 1;
}
